/* The build id compiled into this build (include/p4pc/build_id.h, generated by tools/build_id.py): well formed, and the three accessors agree.
 * Which commit it is depends on where the tree was built (the land check's container has no .git and gets the commit from P4PC_CHECK_SHA), so
 * only the shape is checked here; tests/build_id_test.py checks the values against a real git tree. */
#include <stdio.h>
#include <string.h>

#include "p4pc/build_id.h"

static int failures;
#define CHECK(c) do { if (!(c)) { fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); failures++; } } while (0)

int main(void)
{
    const char *id = p4_build_id(), *commit = p4_build_commit();
    size_t i;

    CHECK(id && commit && *id && *commit);
    if (id && commit && !strcmp(commit, "unknown")) {
        CHECK(!strcmp(id, "unknown") && !p4_build_dirty());
    } else if (id && commit) {
        CHECK(strlen(commit) == 40);
        for (i = 0; i < 40 && commit[i]; i++) CHECK((commit[i] >= '0' && commit[i] <= '9') || (commit[i] >= 'a' && commit[i] <= 'f'));
        CHECK(!strncmp(id, commit, 12));
        CHECK(!strcmp(id + 12, p4_build_dirty() ? "-dirty" : ""));
    }
    printf("build id %s\n", id ? id : "(null)");
    if (failures) return 1;
    return 0;
}
